def find_circle_num_brute(is_connected):
    n = len(is_connected)
    group = list(range(n))                                 # each city's current group id
    changed = True
    while changed:
        changed = False
        for i in range(n):
            for j in range(n):
                if is_connected[i][j] == 1 and group[i] != group[j]:
                    old, new = group[i], group[j]
                    for k in range(n):
                        if group[k] == old:
                            group[k] = new                        # repeated full scans to merge
                    changed = True
    return len(set(group))

