def find_circle_num(is_connected):
    n = len(is_connected)
    visited = [False] * n
    count = 0
    def dfs(u):
        visited[u] = True
        for v in range(n):
            if is_connected[u][v] == 1 and not visited[v]:
                dfs(v)                                              # spread to the whole connected group
    for i in range(n):
        if not visited[i]:
            count += 1                                                # a NEW province found
            dfs(i)
    return count

