public class Main {
    static boolean[] visited;
    static int[][] isConnected;

    static int findCircleNum(int[][] matrix) {
        isConnected = matrix;
        int n = matrix.length;
        visited = new boolean[n];
        int count = 0;
        for (int i = 0; i < n; i++) {
            if (!visited[i]) {
                count++;                                                  // a NEW province found
                dfs(i, n);
            }
        }
        return count;
    }

    static void dfs(int u, int n) {
        visited[u] = true;
        for (int v = 0; v < n; v++) {
            if (isConnected[u][v] == 1 && !visited[v]) dfs(v, n);           // spread to the whole connected group
        }
    }
}

