int findCircleNum(vector<vector<int>>& matrix) {
    isConnected = matrix;
    int n = matrix.size();
    visited.assign(n, false);
    int count = 0;
    for (int i = 0; i < n; i++) {
        if (!visited[i]) {
            count++;                                                       // a NEW province found
            dfs(i, n);
        }
    }
    return count;
}
